function test_pipeline
% Synthetic high-rate filter fixture generated by test_antialias.py.
% This checks acquisition -> ACTUAL MATLAB RLS implementation, not Simulink.
folder=fileparts(mfilename('fullpath')); addpath(folder);
f=load(fullfile(folder,'pipeline_fixture.mat')); clear identify_vbemf;
identify_vbemf(0,0,0,0,0,0);
for n=1:size(f.samples,1)
    u=f.samples(n,:);
    identify_vbemf(u(1),u(2),u(3),u(4),u(5),f.states(n));
end
trace=zeros(4401,5);
for n=1:4401
    [y,~,~]=identify_vbemf(0,0,0,0,220,9);
    trace(n,:)=[y(3) y(4) y(6) y(12) y(13)];
end
assert(y(5)==1 && y(7)==1 && y(12)==4000);
assert(abs(y(3)/.00896-1)<.005);
assert(abs(y(4)/.21-1)<.005);
assert(abs(y(6)/1.8665-1)<.05);
assert(norm(trace(402,1:2)-trace(end,1:2))>1e-5);
fprintf('PASS high-rate LPF + decimation + actual RLS: L=%g H psi=%g Wb R=%g ohm, iterations=%g\n',y(3),y(4),y(6),y(12));
save(fullfile(folder,'synthetic_rls_trace.mat'),'trace');
end
